parameters.text:
=You are the script writer for Milo Story Studio.

Generate one complete children's story script from the approved outline below.

Use only the supplied outline information.
Do not invent new canon rules.
Keep the story age-appropriate and faithful to the approved outline.
Preserve the approved lesson and emotional arc.
Write a complete, polished story suitable for narration.

Approved outline:
Title: {{ $json.title }}
Opening: {{ $('Restore Approved Outline').first().json.opening }}
Setup: {{ $('Restore Approved Outline').first().json.setup }}
Inciting incident: {{ $('Restore Approved Outline').first().json.incitingIncident }}
Rising action: {{ $('Restore Approved Outline').first().json.risingAction }}
Climax: {{ $('Restore Approved Outline').first().json.climax }}
Resolution: {{ $('Restore Approved Outline').first().json.resolution }}
Emotional arc: {{ $('Restore Approved Outline').first().json.emotionalArc }}
Lesson: {{ $json.lesson }}

Return:
scriptText
wordCount
estimatedLengthMinutes

Return only data matching the required structured output.

parameters.jsCode:
const items = $input.all();

const groups = {};

for (const item of items) {
  const storyId = item.json.storyId ?? '';

  if (!groups[storyId]) {
    groups[storyId] = [];
  }

  groups[storyId].push(item.json);
}

const output = [];

for (const [storyId, outlines] of Object.entries(groups)) {

  if (!storyId) {
    output.push({
      json: {
        success: false,
        valid: false,
        errorCode: 'STORY_ID_MISSING',
        message: 'Approved outline is missing storyId.',
        storyId: ''
      }
    });
    continue;
  }

  if (outlines.length !== 1) {
    output.push({
      json: {
        success: false,
        valid: false,
        errorCode: 'APPROVED_OUTLINE_COUNT_INVALID',
        message: 'Story must have exactly one processed APPROVED outline before script generation.',
        storyId,
        approvedOutlineCount: outlines.length
      }
    });
    continue;
  }

  const outline = outlines[0];

  const identifiersValid =
    /^MILO-[0-9]{3}$/.test(storyId) &&
    outline.outlineId === `${storyId}-O01` &&
    /^MILO-[0-9]{3}-C0[1-3]$/.test(outline.conceptId ?? '') &&
    (outline.conceptId ?? '').startsWith(`${storyId}-`);

  if (!identifiersValid) {
    output.push({
      json: {
        success: false,
        valid: false,
        errorCode: 'APPROVED_OUTLINE_INVALID',
        message: 'Approved outline identifiers are invalid or do not belong to storyId.',
        storyId,
        outlineId: outline.outlineId ?? '',
        conceptId: outline.conceptId ?? ''
      }
    });
    continue;
  }

  output.push({
    json: {
      ...outline,
      success: true,
      valid: true
    }
  });
}

return output;
